import {
	Component,
	Event,
	type EventEmitter,
	Listen,
	Prop,
	h,
} from "@stencil/core";
import { caretLeft, caretRight } from "../../../icons";
import { caretLineLeft, caretLineRight } from "../../../icons";
// import {caretLineLeft, caretLineRight} from "@harbor/elements/icons"
import getBootstrapConfig from "../../utils/getBootstrapConfig";

interface I18n {
	perPage?: string;
	goTo?: string;
}

type PageLinkMode = "compact" | "advanced";

/**
 * @since 0.0.6
 * @status stable
 *
 */
@Component({
	tag: "hbr-pagination",
	styleUrl: "pagination.scss",
	shadow: true,
})
export class HbrPagination {
	/**
	 * Current page number
	 */
	@Prop({ mutable: true }) page = 0;

	/**
	 * The total number of records in the page - default
	 */
	@Prop({ mutable: true }) pageSize = 30;

	/**
	 * Total number of records
	 */
	@Prop({ mutable: true }) itemCount = 100;

	/**
	 * Page Length options for the page length selector
	 */
	@Prop({ mutable: true }) pageOptions: number[] = [30, 50, 100];

	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n: I18n = {
		perPage: "Rows per page",
		goTo: "Go to",
	};

	/**
	 * Enable basic (default) mode
	 */
	@Prop({ mutable: true }) basic = true;

	@Prop({ mutable: true }) hoist = false;

	@Prop({ mutable: true }) size: "medium" | "small" = "medium";

	/**
	 * [Deprecated, mode now changes automatically based on the number of pages] Enable advanced mode
	 */
	@Prop({ mutable: true }) advanced = false;

	/**
	 * Determine whether to show pageSize select
	 */
	@Prop({ mutable: true }) sizeChanger = false;

	/**
	 * Determine whether to show detailed page information (like the first and last record number on the page and total number of records)
	 */
	@Prop({ mutable: true }) pageInfo = false;

	/**
	 * Jump to the specified page number directly
	 */
	@Prop({ mutable: true }) showJumper = false;

	/**
	 * disabled the pagination
	 */
	@Prop({ reflect: true }) disabled = false;

	/**
	 * Placement of the select dropdown
	 */
	@Prop({ reflect: true }) placement:
		| "top"
		| "top-start"
		| "top-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "right"
		| "right-start"
		| "right-end"
		| "left"
		| "left-start"
		| "left-end" = "top";

	/**
	 * Show all configured props
	 */
	@Prop({ mutable: true }) showAll = false;

	/**
	 * Arrange configured props. {"0": main_paginator, "1": counts, "2": pageNumberOptions}
	 */
	@Prop({ mutable: true }) orderArray: number[] = [2, 1, 0];

	/**
	 * Toggle between numerical and non-numerical pagination. Available starting from @harbor/elements@2.11.1
	 */
	@Prop({ mutable: true }) nonnumerical = false;

	/** Attributes related to screen readers. */
	@Prop() aria = {
		label: {
			pagination: "Pagination",
			firstPage: "First page",
			lastPage: "Last page",
			nextPage: "Next page",
			previousPage: "Previous page",
			pageNumber: "Page",
			goTo: "Go to page",
		},
		role: "navigation",
	};

	/**
	 * Event emitted when the current page has been changed
	 */
	@Event({ eventName: "hbr-page-changed" }) pageChanged: EventEmitter;

	/**
	 * Event emitted when page size changes
	 */
	@Event({ eventName: "hbr-size-changed" }) sizeChanged: EventEmitter;

	@Listen("hbr-page-changed")
	handleSelected(event: CustomEvent) {
		this.page = event.detail;
		//this.fetch()
	}

	@Listen("hbr-size-changed")
	handleSizeChanged(event: CustomEvent) {
		//this.page=0

		if (this.page === 0) {
			this.page = 0;
			this.pageSize = event.detail.pageSize;
			this.last = Math.ceil(this.itemCount / this.pageSize);
			this.index_start = 0;
			this.index_end = Math.min(this.last, this.index_start + this.limit);
		} else {
			const oldPage = this.page + 1;
			const oldSize = this.pageSize;
			const oldTotal = oldPage * oldSize;
			const firstPage = oldTotal - oldSize + 1;
			this.pageSize = event.detail.pageSize;
			const newSize = this.pageSize;
			const newPage = Math.floor(firstPage / newSize) + 1;
			this.page = newPage - 1;
			this.last = Math.ceil(this.itemCount / this.pageSize);
			let potential_start = 0;
			let potential_end = this.limit;
			if (this.last < this.limit) {
				this.index_start = 0;
				this.index_end = Math.min(this.last, this.index_start + this.limit);
			} else if (newPage > this.last - 4) {
				this.index_start = Math.max(0, this.last - this.limit);
				this.index_end = this.last;
			} else {
				potential_start = Math.max(0, newPage - 2);
				potential_end = Math.min(this.last, potential_start + this.limit);
				this.index_start = potential_start;
				this.index_end = potential_end;
			}
		}
		//this.page=index-1;
	}

	//default page count
	private pageCount = 0;
	private local_basic: boolean;
	private local_advanced: boolean;
	private limit = 5;

	private handleFirst(event) {
		if (this.page !== 0) {
			this.handleSelect(event, 0);
			if (this.advanced && this.page + 1 === this.index_start) {
				this.index_start = this.index_start - 1;
				this.index_end = this.index_end - 1;
			}
		}
	}

	private handleLast(event) {
		if (this.page !== this.pageCount - 1) {
			this.handleSelect(event, this.pageCount - 1);
			if (this.advanced && this.page === this.index_end) {
				this.index_start = this.index_start + 1;
				this.index_end = this.index_end + 1;
			}
		}
	}

	//go to the previous page after clicking previous
	private handlePrevious(event) {
		if (this.page !== 0) {
			this.handleSelect(event, this.page - 1);
			if (this.page + 1 === this.index_start) {
				this.index_start = this.index_start - 1;
				this.index_end = this.index_end - 1;
			}
		}
	}

	//go to the next page after clicking 'next'
	private handleNext(event) {
		if (this.page !== this.pageCount - 1) {
			this.handleSelect(event, this.page + 1);
			if (this.page === this.index_end) {
				this.index_start = this.index_start + 1;
				this.index_end = this.index_end + 1;
			}
		}
	}

	//function to handle click event to be triggered after clicking 'next' in the compact mode
	private handleNextCompact(event: UIEvent) {
		if (this.page !== this.pageCount - 1) {
			this.handleSelectCompact(event, this.page + 1);
		}
	}

	//function to handle click event to be triggered after clicking 'previous' in the compact mode
	private handlePreviousCompact(event) {
		if (this.page !== 0) {
			this.handleSelectCompact(event, this.page - 1);
		}
	}

	//event to be thrown when an index number is selected in the basic mode
	private handleSelect(event: Event, index: number) {
		let newIndex: number = index;
		const target = event.target as HTMLInputElement;
		event.preventDefault();
		if (target?.value) {
			//let index=event.target.value-1;
		}
		if (newIndex >= this.last) {
			newIndex = this.last - 1;
		}
		if (newIndex < 0) {
			newIndex = 0;
		}
		this.pageChanged.emit(newIndex);
		this.updatePageWindow(newIndex);
	}

	private updatePageWindow(index: number) {
		if (index + 1 === this.last) {
			this.index_start = Math.max(0, this.last - this.limit);
			this.index_end = this.last;
		} else if (index + 1 === 1) {
			this.index_start = 0;
			this.index_end = this.limit;
		}
		if (index + 1 >= this.index_end && index + 1 !== this.last) {
			this.index_start = this.last - this.limit;
			this.index_end = this.index_start + this.limit;
		}
		if (index <= this.index_start && index !== 0) {
			this.index_start = index - 1;
			this.index_end = this.index_start + this.limit;
		}
	}

	private handleJump(event) {
		event.preventDefault();
		let index = Number(event.target.value) - 1;
		if (index >= this.last) {
			index = this.last - 1;
		}
		if (index < 0) {
			index = 0;
		}
		this.pageChanged.emit(index);
		this.updatePageWindow(index);
	}

	//event to be thrown when an index number is selected in the compact mode
	private handleSelectCompact(event: UIEvent, index: number) {
		event.preventDefault();
		this.pageChanged.emit(index);
		if (index + 1 === this.index_end && index + 1 !== this.last) {
			this.index_start = this.index_start + 1;
			this.index_end = this.index_end + 1;
		}
		if (index === this.index_start && index !== 0) {
			this.index_start = this.index_start - 1;
			this.index_end = this.index_end - 1;
		}
	}

	private handleSelectAdvanced(event: UIEvent, index: number) {
		event.preventDefault();
		this.pageChanged.emit(index);
	}

	private getNewPage(event) {
		const oldPage = this.page + 1;
		const oldSize = this.pageSize;
		const oldTotal = oldPage * oldSize;
		const firstPage = oldTotal - oldSize + 1;
		const newSize = event.currentTarget.value;
		const newPage = Math.floor(firstPage / newSize);
		return newPage;
	}

	//event to be thrown when page size is changed by the user
	private handlePageSizeChange(event) {
		const page = this.getNewPage(event);
		this.sizeChanged.emit({
			pageSize: Number(event.currentTarget.value),
			page,
		});
	}

	index_start = 0;
	index_end = this.limit;

	last = 0;

	ogAdv = false;

	jumperSize = 1;

	jumperValue;

	private renderPageLink(
		index: number,
		onClick: (event: UIEvent, index: number) => void,
	) {
		return (
			<hbr-link
				part={this.page === index ? "page-number-active" : "pages-number"}
				data-page={index + 1}
				class={this.page === index ? "active" : ""}
				aria-current={this.page === index ? "true" : ""}
				aria={{ label: `${this.aria.label.pageNumber} ${index + 1}` }}
				href="#"
				role="link"
				disabled={this.disabled}
				data-testid={`HbrPagination-page-${index + 1}`}
				onClick={(event) => {
					event.preventDefault();
					onClick(event, index);
					return;
				}}
			>
				{index + 1}
			</hbr-link>
		);
	}

	private renderPageLinks(pages: number[], mode: PageLinkMode) {
		return pages.map((index) =>
			this.renderPageLink(index, (event, pageIndex) => {
				if (mode === "compact") {
					this.handleSelectCompact(event, pageIndex);
				} else {
					this.handleSelectAdvanced(event, pageIndex);
				}
			}),
		);
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		if (this.basic) {
			this.local_basic = true;
		}
		if (this.advanced) {
			this.local_advanced = true;
		}
		if (this.itemCount > 0) {
			//let pages = [];
			const start = this.page * this.pageSize + 1; //starts at 1
			//end = 4;
			const pages = [];
			const end = Math.min(
				this.itemCount,
				this.page * this.pageSize + this.pageSize,
			); //ends at pageSize (total number of pages)

			this.last = Math.ceil(this.itemCount / this.pageSize);

			//for the total number of pages required
			for (let i = 0; i < this.last; i++) {
				pages.push(i);
			}

			//pageCount will become equal to the new length of pages array
			this.pageCount = pages.length;

			if (this.pageCount <= this.limit) {
				// triggering basic mode when the page count is less or equal to 3
				this.local_advanced = false;
				//this.ogAdv=true;
				this.local_basic = true;
			}
			if (this.pageCount > this.limit) {
				// triggering advanced mode when the page count is greater than 3
				this.local_advanced = true;
				this.local_basic = false;
			}

			if (this.showAll) {
				this.showJumper = true;
				this.pageInfo = true;
				this.sizeChanger = true;
			}

			let indices: object[];
			// biome-ignore lint/style/useConst: <explanation>
			let next: object;
			// biome-ignore lint/style/useConst: <explanation>
			let previous: object;
			let ellipses_start = <span />;
			let ellipses_end = <span />;
			let first_link = <span />;
			let last_link: object;
			const nextDisabled = this.page === pages.length - 1;
			const previousDisabled = this.page === 0;
			const getFirstPageArrow = () => (
				<hbr-link
					part={`first ${previousDisabled ? "first-disabled" : ""}`}
					class={{
						"first-page-icon": true,
						"first-disabled": previousDisabled,
					}}
					disabled={this.disabled || previousDisabled}
					href="#"
					role="link"
					aria={{ label: this.aria.label.firstPage }}
					aria-disabled={this.disabled || previousDisabled ? "true" : "false"}
					data-testid="HbrPagination-firstPage"
					onClick={(event) => {
						event.preventDefault();
						this.handleFirst(event);
					}}
				>
					<hbr-visually-hidden>First Page</hbr-visually-hidden>
					<hbr-icon
						asset={customSystemIcons?.["caret-line-left"] || caretLineLeft}
						// asset={arrowLeft}
						// asset={checkSquare}
						class="centered"
						id="first_arrow"
						// size="20px"
					/>
				</hbr-link>
			);
			const firstPageArrow = this.nonnumerical ? getFirstPageArrow() : null;
			const getLastPageArrow = () => (
				<hbr-link
					part={`last ${nextDisabled ? "last-disabled" : ""}`}
					class={{
						"last-page-icon": true,
						"last-disabled": nextDisabled,
					}}
					disabled={this.disabled || nextDisabled}
					href="#"
					role="link"
					aria={{ label: this.aria.label.lastPage }}
					aria-disabled={this.disabled || nextDisabled ? "true" : "false"}
					data-testid="HbrPagination-lastPage"
					onClick={(event) => {
						event.preventDefault();
						this.handleLast(event);
					}}
				>
					<hbr-visually-hidden>Last Page</hbr-visually-hidden>
					<hbr-icon
						asset={customSystemIcons?.["caret-line-right"] || caretLineRight}
						// asset={arrowRight}
						// asset={checkCircle}
						class="centered"
						id="last_arrow"
						// size="20px"
					/>
				</hbr-link>
			);
			const lastPageArrow = this.nonnumerical ? getLastPageArrow() : null;
			next = (
				<hbr-link
					part={`next ${nextDisabled ? "next-disabled" : ""}`}
					class={{
						"next-page-icon": true,
						"next-disabled": nextDisabled,
					}}
					disabled={this.disabled || nextDisabled}
					href="#"
					role="link"
					aria={{ label: this.aria.label.nextPage }}
					aria-disabled={this.disabled || nextDisabled ? "true" : "false"}
					data-testid="HbrPagination-nextLink"
					onClick={(event) => {
						event.preventDefault();
						if (this.local_basic) this.handleNextCompact(event);
						else if (this.local_advanced) this.handleNext(event);
						return;
					}}
				>
					<hbr-visually-hidden>Next Page</hbr-visually-hidden>
					<hbr-icon
						asset={customSystemIcons?.["caret-right"] || caretRight}
						class="centered"
						id="next_arrow"
						// size="20px"
					/>
				</hbr-link>
			);

			previous = (
				<hbr-link
					part={`previous ${previousDisabled ? "previous-disabled" : ""}`}
					class={{
						"previous-page-icon": true,
						"previous-disabled": previousDisabled,
					}}
					disabled={this.disabled || previousDisabled}
					href="#"
					role="link"
					aria={{ label: this.aria.label.previousPage }}
					aria-disabled={this.disabled || previousDisabled ? "true" : "false"}
					data-testid="HbrPagination-previousLink"
					onClick={(event) => {
						event.preventDefault();
						if (this.local_basic) this.handlePreviousCompact(event);
						else if (this.local_advanced) this.handlePrevious(event);
						return;
					}}
				>
					<hbr-visually-hidden>Previous Page</hbr-visually-hidden>
					<hbr-icon
						asset={customSystemIcons?.["caret-left"] || caretLeft}
						class="centered"
						id="previous_arrow"
						// size="20px"
					/>
				</hbr-link>
			);

			//conditions and HTML elements for compact mode
			if (this.local_basic) {
				indices = this.renderPageLinks(
					pages.slice(this.index_start, this.index_end),
					"compact",
				);
			}

			//conditions and HTML elements for advanced mode
			if (this.local_advanced) {
				if (this.page === 0 && this.pageCount > 4) {
					indices = this.renderPageLinks(pages.slice(0, 2), "advanced");

					ellipses_end = <span class="ellipsis">...</span>;

					last_link = this.renderPageLinks(
						pages.slice(this.last - 1, this.last),
						"advanced",
					);
				} else if (this.page === 1 && this.pageCount > 4) {
					first_link = this.renderPageLinks(pages.slice(0, 3), "advanced");
					ellipses_start = <span class="ellipsis">...</span>;
					last_link = this.renderPageLinks(
						pages.slice(this.last - 1, this.last),
						"advanced",
					);
				} else if (this.page === 2 && this.pageCount > 4) {
					first_link = this.renderPageLinks(pages.slice(0, 4), "advanced");
					ellipses_start = <span class="ellipsis">...</span>;
					last_link = this.renderPageLinks(
						pages.slice(this.last - 1, this.last),
						"advanced",
					);
				} else if (this.page >= 3 && this.page <= this.last - 4) {
					first_link = this.renderPageLinks(pages.slice(0, 1), "advanced");

					ellipses_start = <span class="ellipsis">...</span>;

					indices = this.renderPageLinks(
						pages.slice(this.page - 1, this.page + 2),
						"advanced",
					);

					ellipses_end = <span class="ellipsis">...</span>;

					last_link = this.renderPageLinks(
						pages.slice(this.last - 1, this.last),
						"advanced",
					);
				} else if (this.page === this.last - 3 && this.pageCount > 4) {
					first_link = this.renderPageLinks(pages.slice(0, 1), "advanced");

					ellipses_start = <span class="ellipsis">...</span>;

					indices = <span />;
					ellipses_end = <span />;

					last_link = this.renderPageLinks(
						pages.slice(this.last - 4, this.last),
						"advanced",
					);
				} else if (this.page === this.last - 2 && this.pageCount > 4) {
					first_link = this.renderPageLinks(pages.slice(0, 1), "advanced");

					ellipses_start = <span class="ellipsis">...</span>;

					indices = <span />;
					ellipses_end = <span />;

					last_link = this.renderPageLinks(
						pages.slice(this.last - 3, this.last),
						"advanced",
					);
				} else if (this.page >= this.last - 2 && this.page < this.last) {
					first_link = this.renderPageLinks(pages.slice(0, 1), "advanced");

					ellipses_start = <span class="ellipsis">...</span>;

					indices = this.renderPageLinks(
						pages.slice(this.last - 2, this.last),
						"advanced",
					);

					ellipses_end = <span />;
					last_link = <span />;
				}
			}

			//custom hbr select element
			const triggerWidth = this.pageSize?.toString()?.length > 2 ? 74 : 66;
			const popupMinWidth = 122;
			const skidding =
				this.placement === "top-end" || this.placement === "bottom-end"
					? triggerWidth - popupMinWidth
					: 0;
			const hbr_select = (
				<hbr-select
					disabled={this.disabled}
					part="select"
					hoist={this.hoist}
					exportparts="base:select, content:select-content, expand-icon:select-expand-icon"
					class="size-changer"
					size={this.size}
					value={this.pageSize.toString()}
					onHbr-change={(event) => this.handlePageSizeChange(event)}
					data-testid="HbrPagination-select"
					placement={this.placement}
					arialabel={this.i18n.perPage || "Rows per page"}
					style={{
						width: `${triggerWidth}px`,
						"--popup-min-width": `${popupMinWidth}px`,
					}}
					skidding={skidding}
				>
					{this.pageOptions.map((rows) => (
						<hbr-option
							part="menu-item"
							value={rows.toString()}
							data-page={rows.toString()}
							data-testid={`HbrPagination-pageOption-${rows.toString()}`}
						>
							{rows}
						</hbr-option>
					))}
				</hbr-select>
			);

			const input_min = 1;

			const advancedPageElements = !this.nonnumerical
				? [first_link, ellipses_start, indices, ellipses_end, last_link]
				: [];

			const basicPageElements = !this.nonnumerical ? [indices] : [];

			const basic_page_indicators = (
				<div class="generalFlex">
					{[
						firstPageArrow,
						previous,
						...basicPageElements,
						next,
						lastPageArrow,
					]}
				</div>
			);
			const advanced_page_indicators = (
				<div class="generalFlex">
					{[
						firstPageArrow,
						previous,
						...advancedPageElements,
						next,
						lastPageArrow,
					]}
				</div>
			);

			const jumper = (
				<span class="jumpTo">
					<p>{this.i18n.goTo}:&nbsp;</p>
					<hbr-input
						part="jumper"
						disabled={this.disabled}
						size={this.size}
						type="number"
						min={input_min}
						max={this.last}
						style={{ width: "70px" }}
						value={(this.page + 1).toString()}
						on-hbr-change={(event) => this.handleJump(event)}
						data-testId="HbrPagination-pageNumberInput"
						aria={{ label: `${this.aria.label.goTo} ${this.page + 1}` }}
					/>
					&nbsp;<p>/</p>
					&nbsp;<p>{this.last}</p>
				</span>
			);

			let counts = null;
			let pageNumberOptions = null;

			if (this.pageInfo) {
				counts = (
					<span class="counts" data-testId="HbrPagination-pageNumberInfo">
						{start} -{" "}
						{this.page === pages[pages.length - 1] ? this.itemCount : end} of{" "}
						{this.itemCount}
					</span>
				);
			}

			if (this.sizeChanger) {
				pageNumberOptions = (
					<span class="size" part="size">
						<span class="size-description" part="size-description">
							{this.i18n.perPage || "Rows per page"}
						</span>
						{hbr_select}
					</span>
				);
			}

			const main_paginator = (
				<span class="pages">
					<span class={this.local_basic ? "main_indices_basic" : ""}>
						{!this.local_advanced && basic_page_indicators}
						{!this.local_advanced && this.showJumper && jumper}
					</span>
					<span class={this.local_advanced ? "main_indices" : ""}>
						{/* all the indices mapped in order */}
						{this.local_advanced && advanced_page_indicators}
						{this.local_advanced && this.showJumper && jumper}
					</span>
				</span>
			);

			const indexDictionary = {
				"0": main_paginator,
				"1": counts,
				"2": pageNumberOptions,
			};

			const elements = [];

			if (this.orderArray.toString() !== "[0, 1, 2]") {
				for (let i = 0; i < 3; i++) {
					elements[i] = indexDictionary[this.orderArray[i].toString()];
				}
			} else {
				elements[0] = !this.nonnumerical ? main_paginator : null;
				elements[1] = counts;
				elements[2] = pageNumberOptions;
			}

			return (
				<div
					class="paginator"
					part="base"
					role={this.aria.role}
					aria-label={this.aria.label.pagination}
				>
					{elements[0]}
					<span class="demographics">
						{elements[1]}
						{elements[2]}
					</span>
				</div>
			);
		}
	}
}
